INSERT INTO user_scope_migrations(source_workspace_id,source_root,disposition,profile_ids,sql_done_at)
SELECT c.workspace_id,c.source_root,
CASE WHEN EXISTS (SELECT 1 FROM worktrees WHERE workspace_id=c.workspace_id)
 OR EXISTS (SELECT 1 FROM automation_jobs WHERE loop_workspace_id=c.workspace_id)
 OR EXISTS (SELECT 1 FROM automation_triggers WHERE loop_workspace_id=c.workspace_id)
 THEN 'keep_project' ELSE 'migrate' END,
(SELECT json_group_array(profile_id) FROM user_migration_profiles p WHERE p.source_workspace_id=c.workspace_id),datetime('now')
FROM user_scope_migration_context c JOIN workspaces w ON w.id=c.workspace_id;
CREATE TEMP TABLE user_migration_sources AS SELECT source_workspace_id AS id FROM user_scope_migrations WHERE disposition='migrate';
UPDATE automation_runs SET workspace_id='' WHERE workspace_id IN (SELECT id FROM user_migration_sources);
